# Rules whose regex runs on normalized text (invisible characters removed, look-alikes mapped, letter spacing collapsed).
NORMALIZED_FAMILIES: list[str] = ["INJ01", "INJ03", "INJ11", "INJ12", "REF01", "REF03", "LEAK01", "LEAK03", "MEM03"]

# Built-in slash commands and common skill names a skill should not shadow.
SHADOW_NAMES: set[str] = {"help", "clear", "compact", "config", "cost", "doctor", "exit", "init", "login", "logout", "memory", "model", "permissions", "review", "status", "terminal-setup", "vim", "resume", "rewind", "hooks", "mcp", "agents", "plugin", "context", "bug", "add-dir", "fast", "loop", "run", "simplify", "security-review", "code-review", "update-config", "keybindings-help", "fewer-permission-prompts", "claude-api", "skill-creator", "commit", "test", "build", "deploy", "debug", "plan"}

# Words that make a description match everyday requests.
BROAD_TRIGGER: re.Pattern[str] = scan_re(r'\b(for|on|with|in|to)\s+(any|all|every)\s+(task|request|question|conversation|prompt|message)s?\b|\bhelp(s|ing)?\s+with\s+(anything|everything)\b|\balways\s+(use|invoke|load|apply)\s+(this|it)\b|\b(use|invoke|load)\s+(this\s+skill\s+)?(for|on|in)\s+(every|all|any)\b|\bwhenever\s+(the\s+user\s+)?(asks?|says?|types?|writes?|mentions?)\s+(anything|something)\b|\bproactively\b[^.\n]{0,40}\b(always|every)\b', 'i')
